#!/usr/bin/env node
/**
 * Tests that the lite dev-loop docs say what the code does: the `targeted` arg and its JS/TS limit, the reader A rule,
 * and the After-OK gate that is normally skipped.
 *
 * Generated by Claude Code at the user's request.
 */

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

const read = (p) => readFileSync(fileURLToPath(new URL(`../${p}`, import.meta.url)), 'utf8');
const LOOP = read('skills/deliver/references/loop.md');
const README = read('README.md');
const META = read('workflows/dev-loop.js').slice(0, 1500);

test('given the loop reference, when it describes `targeted`, then it names the template, the JS/TS limit and that .NET stays full', () => {
  // Given / When
  const row = LOOP.split('\n').find((l) => l.startsWith('| `targeted`')) ?? '';
  // Then
  assert.match(row, /\{files\}/);
  assert.match(row, /JS\/TS/);
  assert.match(row, /\.NET stays full/);
});

test('given the README and the workflow meta, when they list the args, then both carry targeted with the JS/TS limit', () => {
  // Given / When / Then
  assert.match(README, /`targeted` \(JS\/TS repos/);
  assert.match(META, /targeted/);
  assert.match(META, /JS\/TS/);
});

test('given the loop reference, when it states the reader A rule, then risky alone no longer triggers it', () => {
  // Given / When / Then
  assert.match(LOOP, /Reader A runs on a block only when the run has a `security` or `data` axis or the block's gate was red before green/);
  assert.match(LOOP, /`risky: true` alone no longer triggers it/);
});

test('given the loop reference, when it describes After OK, then the gate normally returns skipped: tree unchanged', () => {
  // Given / When / Then
  assert.match(LOOP, /normally returns `skipped: tree unchanged`/);
});
